","n":4,"of":5,"big":"FC St. Pauli","line":"The skull and crossbones started as a pirate flag on a broomstick at the Millerntor in the 1980s; the club bought the rights to the design in 1999.","shout":"FOREVER!","label":"FC ST. PAULI · FAN LIFE"}},{"t":"L-SLIDE","data":{"club":{"id":"st-pauli","name":"FC St. Pauli"},"crestName":"FC St. Pauli","s":"cta","n":5,"of":5,"title":"FC St. Pauli has its own home on FAN LIFE. Come in."}}]}}'::jsonb),
